    if (w.conf[1] > 0) ranged = NameOf(w.conf[1]);
    out[0] = melee; out[1] = ranged;
    if (w.prev[0] > 0) melee = NameOf(w.prev[0]);
    if (w.prev[1] > 0) ranged = NameOf(w.prev[1]);
    out[2] = melee; out[3] = ranged;
}
