{
    if (in[0] != "") w.conf[0] = IndexOf(in[0]);
    if (in[1] != "") w.conf[1] = IndexOf(in[1]);
    if (in[2] != "") w.prev[0] = IndexOf(in[2]);
    if (in[3] != "") w.prev[1] = IndexOf(in[3]);
}
