    if (g_posStart.X != 1.5f || g_posStart.Y != -2.5f || g_posStart.Z != 3.25f) return 5;
    if (g_posEnd.X != 1.5f || g_posEnd.Y != -2.5f || g_posEnd.Z != 3.25f) return 6;
